 const backlogItems=ordered.filter(i=>!i.sprint);const future=document.createElement('div');future.className='backlogSprint';future.innerHTML='<div class="sprintHead"><span>Backlog</span><span class="sprintGoal">Rank and plan work before moving it into a sprint.</span><span class="sprintStats">'+backlogItems.length+' work items</span></div>';backlogItems.forEach(i=>{const r=document.createElement('div');r.className='backlogRow';r.dataset.issue=i.key;r.innerHTML='<b>'+esc(i.key)+'</b><span>'+esc(i.summary)+'</span><span>'+esc(i.status)+'</span><span>'+esc(i.assignee||'')+'</span><span>'+esc(i.points??'')+'</span>';r.onclick=()=>openIssue(i.key);future.appendChild(r)});if(!backlogItems.length)future.insertAdjacentHTML('beforeend','<div class="empty">No unplanned work items.</div>');wrap.appendChild(future);refs.content.replaceChildren(wrap);
