 refs.content.innerHTML='<div class="summaryGrid"><div class="summaryCard"><div class="summaryTitle">Project progress</div><div class="reportStats"><div class="statCard"><div class="statValue">'+state.issues.length+'</div><div class="statLabel">Work items</div></div><div class="statCard"><div class="statValue">'+open+'</div><div class="statLabel">Open</div></div><div class="statCard"><div class="statValue">'+done+'</div><div class="statLabel">Done</div></div><div class="statCard"><div class="statValue">'+donePts+'/'+pts+'</div><div class="statLabel">Story points</div></div></div><div style="margin-top:14px"><div class="progressBar"><div class="progressFill" style="width:'+(pts?Math.round(donePts/pts*100):0)+'%"></div></div></div></div><div class="summaryCard"><div class="summaryTitle">Work types</div>'+Object.entries(byType).map(([k,v])=>'<div class="miniMetric"><span>'+esc(k)+'</span><b>'+v+'</b></div>').join('')+'</div><div class="summaryCard"><div class="summaryTitle">Sprint</div><div class="miniMetric"><span>Name</span><b>'+esc(state.sprint?.name||'')+'</b></div><div class="miniMetric"><span>Status</span><b>'+esc(state.sprint?.status||'')+'</b></div><div class="miniMetric"><span>Goal</span><span>'+esc(state.sprint?.goal||'')+'</span></div></div><div class="summaryCard"><div class="summaryTitle">Recent activity</div>'+state.issues.slice(0,6).map(i=>'<div class="miniMetric"><span>'+esc(i.key)+' '+esc(i.summary)+'</span><span>'+esc(i.status)+'</span></div>').join('')+'</div></div>';
