 const head='<div class="timelineHead"><div>Work item</div>'+['Week 1','Week 2','Week 3','Week 4','Week 5','Week 6'].map(x=>'<div>'+x+'</div>').join('')+'</div>';let rows='';state.issues.slice(0,12).forEach((i,idx)=>{const start=idx%4,end=Math.min(5,start+1+(idx%2));rows+='<div class="timelineRow"><div><b>'+esc(i.key)+'</b> '+esc(i.summary)+'</div>'+Array.from({length:6},(_,n)=>'<div>'+(n>=start&&n<=end?'<div class="timelineBar" style="opacity:'+(isDone(i)?'.55':'1')+'"></div>':'')+'</div>').join('')+'</div>'});refs.content.innerHTML='<div class="timeline">'+head+rows+'</div>';
