const ISSUE_PANEL_ACTIONS = new Set([
 'openIssue','setStatus','moveIssue','setField','assignIssue','setDescription',
 'addLabel','removeLabel','toggleWatch','addAttachment','addSubtask','addLink',
 'addComment','typeComment','setDueDate','setParent','setFixVersion','setEstimate','logWork','linkDevelopment','createBranch','linkCommit','linkPullRequest','setBuildStatus','setDeploymentStatus','transitionIssue'
]);
const CREATE_MODAL_ACTIONS = new Set(['openCreateIssue','fillCreateField','submitCreateIssue']);
function targetNeedsIssuePanel(target){
 if(typeof target==='string')return ['status','assign','watch','comment','latestComment'].includes(target);
 return false;
}
function actionNeedsIssuePanel(st){
 const action=st?.action||'',d=st?.data||{};
 if(ISSUE_PANEL_ACTIONS.has(action))return true;
 if(['openMenu','pressButton','highlightTarget','moveCursor'].includes(action))return targetNeedsIssuePanel(d.target);
 return false;
}
function clearIssuePanelState(){selectedIssue=null;refs.issuePanel.classList.remove('show')}
function clearStandupState(){clearInterval(standupTimerHandle);standupTimerHandle=0;refs.standupBar.classList.remove('show');refs.standupTimer.textContent='00:00'}
function prepareReplayStep(st){
 const action=st?.action||'';
 // The issue drawer is step-local. Preserve it only for an explicit issue workflow
 // or an issue-specific control immediately following openIssue/createIssue.
 if(!actionNeedsIssuePanel(st))clearIssuePanelState();

 // Create-issue field entry is a deliberate modal chain. Any unrelated step closes it.
 if(!CREATE_MODAL_ACTIONS.has(action))closeModal();

 // Stand-up is also transient. Keep it only through its start/end workflow.
 if(action!=='startStandup'&&action!=='endStandup')clearStandupState();

 // Menus/toasts are never allowed to leak into the next replayed step.
 refs.menu.classList.remove('show');
 refs.notification.classList.remove('show');
}
